#include <iostream>
#include <string>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    string cows;
    in >> n >> cows;
    int previous = -1, reversals = 0;
    for (int i = 0; i < n; i += 2) {
        if (cows[i] == cows[i + 1]) continue;
        int current = cows[i] == 'G' ? 1 : 0;
        if (previous != -1 && previous != current) ++reversals;
        previous = current;
    }
    if (previous == 1) ++reversals;
    out << reversals << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
