#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<char> direction(n);
    vector<long long> threshold(n);
    for (int i = 0; i < n; ++i) in >> direction[i] >> threshold[i];
    int answer = n;
    for (long long location : threshold) {
        int lies = 0;
        for (int i = 0; i < n; ++i) {
            if (direction[i] == 'L' && location > threshold[i]) ++lies;
            if (direction[i] == 'G' && location < threshold[i]) ++lies;
        }
        answer = min(answer, lies);
    }
    out << answer << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
