#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<long long> stock(n + 1);
    long long total = 0;
    for (int i = 1; i <= n; ++i) { in >> stock[i]; total += stock[i]; }
    int k;
    in >> k;
    vector<vector<int> > recipe(n + 1);
    for (int r = 0; r < k; ++r) {
        int output, ingredients;
        in >> output >> ingredients;
        recipe[output].resize(ingredients);
        for (int& ingredient : recipe[output]) in >> ingredient;
    }
    auto feasible = [&](long long target) {
        vector<long long> demand(n + 1, 0);
        demand[n] = target;
        for (int i = n; i >= 1; --i) {
            if (demand[i] > total) return false;
            if (demand[i] <= stock[i]) continue;
            if (recipe[i].empty()) return false;
            long long missing = demand[i] - stock[i];
            for (int ingredient : recipe[i])
                demand[ingredient] = min(total + 1, demand[ingredient] + missing);
        }
        return true;
    };
    long long low = 0, high = total;
    while (low < high) {
        long long middle = low + (high - low + 1) / 2;
        if (feasible(middle)) low = middle;
        else high = middle - 1;
    }
    out << low << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
